#!/usr/bin/env python3
"""Remove exact agent fingerprints from all effective root key files."""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import pwd
import shutil
import subprocess
import tempfile
from pathlib import Path


def read_fps(path: str) -> set[str]:
    values = {
        line.strip() for line in Path(path).read_text(encoding="utf-8").splitlines()
        if line.strip() and not line.lstrip().startswith("#")
    }
    if not values or any(not item.startswith("SHA256:") for item in values):
        raise SystemExit(f"invalid or empty fingerprint file: {path}")
    return values


def fingerprint(line: str) -> str:
    with tempfile.NamedTemporaryFile("w", encoding="utf-8", delete=False) as stream:
        stream.write(line.rstrip("\n") + "\n")
        name = stream.name
    try:
        completed = subprocess.run(
            ["ssh-keygen", "-lf", name], check=True, text=True, capture_output=True
        )
        parts = completed.stdout.split()
        if len(parts) < 2 or not parts[1].startswith("SHA256:"):
            raise SystemExit("ssh-keygen emitted no SHA256 fingerprint")
        return parts[1]
    finally:
        os.unlink(name)


def expand(token: str, user: str, home: str) -> Path:
    sentinel = "@@P5_PERCENT@@"
    value = token.replace("%%", sentinel).replace("%h", home).replace("%u", user)
    value = value.replace(sentinel, "%")
    if "%" in value:
        raise SystemExit(f"unsupported AuthorizedKeysFile token: {token}")
    return Path(value if value.startswith("/") else str(Path(home) / value))


def effective_tokens(user: str, host: str, addr: str) -> list[str]:
    completed = subprocess.run(
        ["/usr/sbin/sshd", "-T", "-C", f"user={user},host={host},addr={addr}"],
        check=True, text=True, capture_output=True,
    )
    rows = [
        line.split(maxsplit=1)[1]
        for line in completed.stdout.splitlines()
        if line.lower().startswith("authorizedkeysfile ")
    ]
    if len(rows) != 1:
        raise SystemExit("effective AuthorizedKeysFile is ambiguous")
    tokens = rows[0].split()
    if not tokens or tokens == ["none"]:
        raise SystemExit("root AuthorizedKeysFile is none/empty")
    return tokens


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--user", default="root")
    parser.add_argument("--host", required=True)
    parser.add_argument("--addr", required=True)
    parser.add_argument("--agent-fingerprints", required=True)
    parser.add_argument("--allowed-fingerprints", required=True)
    parser.add_argument("--backup-dir")
    parser.add_argument("--apply", action="store_true")
    parser.add_argument("--verify-absent", action="store_true")
    parser.add_argument("--report", required=True)
    args = parser.parse_args()
    if args.apply and args.verify_absent:
        raise SystemExit("--apply and --verify-absent are mutually exclusive")
    if args.apply and not args.backup_dir:
        raise SystemExit("--backup-dir is required with --apply")
    if os.geteuid() != 0:
        raise SystemExit("must run as root")
    agent = read_fps(args.agent_fingerprints)
    allowed = read_fps(args.allowed_fingerprints)
    if agent & allowed:
        raise SystemExit("agent and recovery allowlists overlap")
    account = pwd.getpwnam(args.user)
    tokens_before = effective_tokens(args.user, args.host, args.addr)
    paths = [expand(token, args.user, account.pw_dir) for token in tokens_before]
    resolved = [str(path.resolve(strict=False)) for path in paths]
    if len(set(resolved)) != len(resolved):
        raise SystemExit("duplicate/aliased effective AuthorizedKeysFile paths")
    plan: list[tuple[Path, list[str], list[str], list[str]]] = []
    report_paths = []
    for path in paths:
        if path.is_symlink():
            raise SystemExit(f"symlink AuthorizedKeysFile rejected: {path}")
        lines = path.read_text(encoding="utf-8").splitlines(keepends=True) if path.exists() else []
        kept: list[str] = []
        before: list[str] = []
        removed: list[str] = []
        for line in lines:
            if not line.strip() or line.lstrip().startswith("#"):
                kept.append(line)
                continue
            fp = fingerprint(line)
            before.append(fp)
            if fp in agent:
                removed.append(fp)
            elif fp in allowed:
                kept.append(line)
            else:
                raise SystemExit(f"unallowlisted root recovery key {fp} in {path}")
        plan.append((path, kept, before, removed))
        report_paths.append({
            "path": str(path), "before_fingerprints": before,
            "removed_agent_fingerprints": removed,
        })
    if not args.verify_absent and not any(item[3] for item in plan):
        raise SystemExit("no configured agent fingerprint found in root effective paths")
    if args.verify_absent and any(item[3] for item in plan):
        raise SystemExit("agent fingerprint still present in an effective root path")
    if args.apply:
        backup = Path(args.backup_dir)
        backup.mkdir(parents=True, exist_ok=False, mode=0o700)
        for index, (path, kept, _before, _removed) in enumerate(plan):
            if path.exists():
                shutil.copy2(path, backup / f"{index:02d}-{path.name}")
            path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
            fd, temporary = tempfile.mkstemp(prefix=".p5-akf-", dir=path.parent)
            try:
                os.write(fd, "".join(kept).encode("utf-8"))
                os.fchmod(fd, 0o600)
            finally:
                os.close(fd)
            os.replace(temporary, path)
            os.chown(path, account.pw_uid, account.pw_gid)
    tokens_after = effective_tokens(args.user, args.host, args.addr)
    if tokens_after != tokens_before:
        raise SystemExit("effective AuthorizedKeysFile changed during sanitation")
    if args.apply:
        for path, _kept, _before, _removed in plan:
            for line in path.read_text(encoding="utf-8").splitlines():
                if line.strip() and not line.lstrip().startswith("#"):
                    fp = fingerprint(line)
                    if fp in agent or fp not in allowed:
                        raise SystemExit(f"post-cutover root key proof failed: {fp}")
    output = {
        "status": "APPLIED" if args.apply else ("ABSENT_VERIFIED" if args.verify_absent else "PLANNED"),
        "user": args.user,
        "effective_tokens": tokens_after,
        "paths": report_paths,
        "private_keys_read": False,
    }
    Path(args.report).write_text(
        json.dumps(output, sort_keys=True, separators=(",", ":")) + "\n",
        encoding="utf-8", newline="\n",
    )
    print(json.dumps(output, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
